<script setup lang="ts">
import {ArrowLeft,CheckCircle2,LockKeyhole,Flag,Box} from 'lucide-vue-next'
import MarkdownView from '~/components/ui/MarkdownView.vue'
import {useAuth} from '~/composables/useAuth'
import type {Challenge} from '~/shared/challenges'
definePageMeta({layout:'learning',key:r=>r.fullPath})
const id=String(useRoute().params.id),{currentUser}=useAuth(),learner=computed(()=>currentUser.value?.id||'')
const {data,error,refresh}=await useFetch<{data:Challenge}>(`/api/challenges/${id}`,{key:`challenges:detail:${id}`,watch:[learner]})
const ready=ref(false);onMounted(()=>{ready.value=true})
const c=computed(()=>data.value?.data),answers=ref<Record<string,string>>({}),feedback=ref<Record<string,string>>({}),busy=ref(false)
watch(learner,()=>{answers.value={};feedback.value={}})
useHead(()=>({title:c.value?`${c.value.title} — AttackBox`:'挑战 — AttackBox',meta:[{name:'description',content:c.value?.summary||'安全学习挑战'}]}))
async function submit(stageId:string){if(busy.value)return;busy.value=true;try{const r=await $fetch<{data:{correct:boolean}}>(`/api/challenges/${id}/attempt`,{method:'POST',body:{stageId,flag:answers.value[stageId]}});feedback.value[stageId]=r.data.correct?'阶段已通过':c.value?.stages.find(s=>s.id===stageId)?.hint?'Flag 不正确，可以查看提示后再试':'Flag 不正确，可以继续尝试';if(r.data.correct){delete answers.value[stageId];await refresh();clearNuxtData('challenges:list')}}catch(e:any){feedback.value[stageId]=e?.data?.message||'提交失败，请重试'}finally{busy.value=false}}
</script>
<template><main class="challenge-detail"><NuxtLink to="/challenges" class="back"><ArrowLeft :size="14"/>挑战列表</NuxtLink><p v-if="error" role="alert">挑战不存在或尚未发布。</p><template v-else-if="c"><header><div class="eyebrow">{{c.category||'综合挑战'}}</div><h1>{{c.title}}</h1><p>{{c.summary}}</p><div class="progress"><Flag :size="16"/>{{currentUser?`${c.completedStages} / ${c.totalStages} 阶段已完成`:`${c.totalStages} 个阶段`}}<span v-if="currentUser&&c.isCompleted" class="success"><CheckCircle2 :size="16"/>挑战已完成</span></div></header><MarkdownView :content="c.bodyMarkdown"/><TargetEnvironment v-if="c.target" :context="{kind: 'challenge', challengeId: String($route.params.id)}" /><details v-if="c.target" class="target"><summary><Box :size="17"/>目标环境{{c.target.status==='configured'?` · ${c.target.name}`:'暂不可用'}}</summary><template v-if="c.target.status==='configured'"><p>{{c.target.description}}</p><p>容器服务端口：{{c.target.ports.map(p=>`${p.port}/${p.protocol.toUpperCase()}`).join('、')||'未配置'}}</p><p class="instructions">{{c.target.accessInstructions}}</p><small>独享实例，停止后清除靶机内修改。</small></template><p v-else>关联环境暂不可用，任务与解题记录仍可查看。</p></details><section aria-label="阶段任务" class="stage-list"><article v-for="(s,index) in c.stages" :key="s.id" class="stage"><header class="stage-heading"><span class="number">{{String(index+1).padStart(2,'0')}}</span><h2>{{s.title}}</h2><CheckCircle2 v-if="s.passedAt" class="success" :size="20"/><LockKeyhole v-else-if="s.locked" :size="18"/></header><MarkdownView :content="s.promptMarkdown"/><details v-if="s.hint" class="hint"><summary>查看提示</summary><p>{{s.hint}}</p></details><p v-if="s.passedAt" class="success" role="status">阶段已通过</p><NuxtLink v-else-if="!currentUser" :to="`/auth?returnTo=${encodeURIComponent('/challenges/'+id)}`" class="login">登录后提交 Flag</NuxtLink><p v-else-if="s.locked" class="locked">完成前面的阶段后即可提交。</p><form v-else @submit.prevent="submit(s.id)"><label class="sr-only" :for="`flag-${s.id}`">阶段 {{index+1}} Flag</label><input :id="`flag-${s.id}`" v-model="answers[s.id]" placeholder="flag{...}" maxlength="2000" autocomplete="off" spellcheck="false" :disabled="busy||!ready"/><button :disabled="busy||!ready||!answers[s.id]?.trim()">{{busy?'校验中…':'提交 Flag'}}</button></form><p v-if="feedback[s.id]&&!s.passedAt" role="status">{{feedback[s.id]}}</p></article></section></template></main></template>
<style scoped>
.challenge-detail{width:100%;max-width:1000px;margin:auto;padding:36px 28px 80px;color:var(--ink)}.back{display:inline-flex;gap:7px;align-items:center;color:var(--muted);text-decoration:none;font-size:12px}header{padding:34px 0 28px}h1{font-size:36px;margin:12px 0 18px}header>p{color:var(--muted);font-size:15px;line-height:1.8}.eyebrow{font-size:12px;color:var(--green)}.progress{display:flex;align-items:center;gap:10px;font-size:13px;color:var(--muted)}.success{color:var(--green);display:inline-flex;align-items:center;gap:7px}.progress .success{margin-left:auto}.stage-list{margin-top:38px}.stage{border-top:1px solid var(--line);padding:28px 0}.stage-heading{display:flex;align-items:center;gap:15px;padding:0;margin-bottom:20px}.stage-heading h2{flex:1;font-size:20px;margin:0}.number{color:var(--muted);font:20px ui-monospace,monospace}.hint{font-size:13px;color:var(--muted);margin:20px 0}.hint summary{cursor:pointer}.hint p,.instructions{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8}form{display:flex;gap:10px;margin:22px 0}input{flex:1;min-width:0;padding:12px;background:var(--paper);color:var(--ink);border:1px solid var(--line);border-radius:6px;font:13px ui-monospace,monospace}button{background:var(--ink);color:var(--paper);border:0;border-radius:6px;padding:10px 18px;cursor:pointer}button:disabled{opacity:.5;cursor:default}.locked,article>p,.login{font-size:13px}.locked{color:var(--muted)}.login{color:var(--green)}.target{background:var(--paper);border:1px solid var(--line);border-radius:8px;padding:18px 22px;margin-top:28px;font-size:13px}.target summary{display:flex;align-items:center;gap:9px;cursor:pointer}.target small{color:var(--muted)}
</style>
